def test_restock_adds_to_existing():
    stock = {"A1": 5, "B2": 1}
    assert inventory.restock(stock, "A1", 3) == 8
    assert inventory.restock(stock, "A1", 2) == 10
    assert stock == {"A1": 10, "B2": 1}


def test_restock_new_sku_and_validation():
    stock = {}
    assert inventory.restock(stock, "Z9", 4) == 4
    with pytest.raises(ValueError):
        inventory.restock(stock, "Z9", 0)
    assert stock == {"Z9": 4}


def test_every_other_function_unchanged():
    src = pathlib.Path("inventory.py").read_text().replace("\r\n", "\n")
    tree = ast.parse(src)
    found = {n.name: ast.get_source_segment(src, n) for n in tree.body
             if isinstance(n, ast.FunctionDef)}
    found.pop("restock", None)
    missing = sorted(EXPECTED.keys() - found.keys())
    extra = sorted(found.keys() - EXPECTED.keys())
    assert not missing and not extra, f"missing: {missing}, unexpected: {extra}"
    changed = [n for n in EXPECTED if found[n].strip() != EXPECTED[n]]
    assert not changed, f"functions other than restock were changed: {changed}"
